-- Generated by mapping/generate_sql.py — Addresses->Comms
-- Candidate mobile (Addresses.Phone of the candidate's home address)
SET NOCOUNT ON;
USE [RecruitPlatform_Target];
DECLARE @mid NVARCHAR(200) = N'Addresses->Comms';
IF OBJECT_ID('tempdb..#stage') IS NOT NULL DROP TABLE #stage;
-- 1. stage: source rows with every target value computed
SELECT p.[Person_ID] AS [__src_key],
       k.target_id AS [ID],
       ((SELECT km.target_id FROM mig.KeyMap km WHERE km.target_table = 'Applicant' AND km.source_table = 'Person' AND km.source_key = CAST(p.[Person_ID] AS NVARCHAR(200)))) AS [ObjectID],
       N'Applicant' AS [ObjectType],
       s.[Phone] AS [Value],
       N'Mobile' AS [Type],
       p.[Deleted] AS [Deleted],
       CAST(s.[CreatedBy] AS NVARCHAR(200)) AS [__raw_AddedBy],
       fk6.target_id AS [AddedBy],
       CAST(p.[UpdatedBy] AS NVARCHAR(200)) AS [__raw_UpdatedBy],
       fk7.target_id AS [UpdatedBy]
INTO #stage
FROM [Cobaltdesk_Legacy].dbo.[Addresses] s
     INNER JOIN [Cobaltdesk_Legacy].dbo.[Person] p ON p.[AddressID] = s.[AddressID]
JOIN mig.KeyMap k ON k.target_table = N'Comms' AND k.source_table = N'Addresses' AND k.source_key = CAST(p.[Person_ID] AS NVARCHAR(200))
LEFT JOIN mig.KeyMap fk6 ON fk6.target_table = N'User' AND fk6.source_table = N'Recruiter' AND fk6.source_key = CAST(s.[CreatedBy] AS NVARCHAR(200))
LEFT JOIN mig.KeyMap fk7 ON fk7.target_table = N'User' AND fk7.source_table = N'Recruiter' AND fk7.source_key = CAST(p.[UpdatedBy] AS NVARCHAR(200))
WHERE 1 = 1 AND (p.[Associate] = 0 AND s.[Phone] IS NOT NULL);
INSERT INTO mig.LoadLog (mapping_id, step, row_count) VALUES (@mid, N'staged', @@ROWCOUNT);
-- 2. reject rows whose parent was not migrated (would break the FK)
INSERT INTO mig.Rejects (mapping_id, target_table, target_column, source_table, source_key, action, reason)
SELECT @mid, N'Comms', N'AddedBy', N'Addresses', CAST([__src_key] AS NVARCHAR(200)), N'rejected', N'AddedBy: no User migrated for legacy Recruiter ' + [__raw_AddedBy]
FROM #stage WHERE [__raw_AddedBy] IS NOT NULL AND [AddedBy] IS NULL;
INSERT INTO mig.Rejects (mapping_id, target_table, target_column, source_table, source_key, action, reason)
SELECT @mid, N'Comms', N'UpdatedBy', N'Addresses', CAST([__src_key] AS NVARCHAR(200)), N'rejected', N'UpdatedBy: no User migrated for legacy Recruiter ' + [__raw_UpdatedBy]
FROM #stage WHERE [__raw_UpdatedBy] IS NOT NULL AND [UpdatedBy] IS NULL;
-- children of rejected rows must not find them: drop their keys
DELETE k FROM mig.KeyMap k WHERE k.target_table = N'Comms' AND k.target_id IN (SELECT k2.target_id FROM mig.KeyMap k2 WHERE k2.target_table = N'Comms' AND k2.source_table = N'Addresses' AND k2.source_key IN (SELECT source_key FROM mig.Rejects WHERE mapping_id = @mid AND action = N'rejected'));
INSERT INTO mig.Rejects (mapping_id, target_table, target_column, source_table, source_key, action, reason)
SELECT @mid, N'Comms', N'ObjectID', N'Addresses', CAST([__src_key] AS NVARCHAR(200)), N'truncated', N'ObjectID: longer than 50 characters, cut to fit' FROM #stage WHERE LEN(CAST([ObjectID] AS NVARCHAR(MAX))) > 50;
INSERT INTO mig.Rejects (mapping_id, target_table, target_column, source_table, source_key, action, reason)
SELECT @mid, N'Comms', N'ObjectType', N'Addresses', CAST([__src_key] AS NVARCHAR(200)), N'truncated', N'ObjectType: longer than 50 characters, cut to fit' FROM #stage WHERE LEN(CAST([ObjectType] AS NVARCHAR(MAX))) > 50;
INSERT INTO mig.Rejects (mapping_id, target_table, target_column, source_table, source_key, action, reason)
SELECT @mid, N'Comms', N'Value', N'Addresses', CAST([__src_key] AS NVARCHAR(200)), N'truncated', N'Value: longer than 50 characters, cut to fit' FROM #stage WHERE LEN(CAST([Value] AS NVARCHAR(MAX))) > 50;
INSERT INTO mig.Rejects (mapping_id, target_table, target_column, source_table, source_key, action, reason)
SELECT @mid, N'Comms', N'Type', N'Addresses', CAST([__src_key] AS NVARCHAR(200)), N'truncated', N'Type: longer than 50 characters, cut to fit' FROM #stage WHERE LEN(CAST([Type] AS NVARCHAR(MAX))) > 50;
INSERT INTO mig.Rejects (mapping_id, target_table, target_column, source_table, source_key, action, reason)
SELECT @mid, N'Comms', N'AddedBy', N'Addresses', CAST([__src_key] AS NVARCHAR(200)), N'truncated', N'AddedBy: longer than 50 characters, cut to fit' FROM #stage WHERE LEN(CAST([AddedBy] AS NVARCHAR(MAX))) > 50;
INSERT INTO mig.Rejects (mapping_id, target_table, target_column, source_table, source_key, action, reason)
SELECT @mid, N'Comms', N'UpdatedBy', N'Addresses', CAST([__src_key] AS NVARCHAR(200)), N'truncated', N'UpdatedBy: longer than 50 characters, cut to fit' FROM #stage WHERE LEN(CAST([UpdatedBy] AS NVARCHAR(MAX))) > 50;
-- 3. load
INSERT INTO dbo.[Comms] ([ID], [ObjectID], [ObjectType], [Value], [Type], [Deleted], [AddedBy], [UpdatedBy])
SELECT TRY_CONVERT(INT, [ID]),
       CAST(LEFT(CAST([ObjectID] AS NVARCHAR(MAX)), 50) AS NVARCHAR(50)),
       CAST(LEFT(CAST([ObjectType] AS NVARCHAR(MAX)), 50) AS NVARCHAR(50)),
       CAST(LEFT(CAST([Value] AS NVARCHAR(MAX)), 50) AS NVARCHAR(50)),
       CAST(LEFT(CAST([Type] AS NVARCHAR(MAX)), 50) AS NVARCHAR(50)),
       TRY_CONVERT(BIT, [Deleted]),
       CAST(LEFT(CAST([AddedBy] AS NVARCHAR(MAX)), 50) AS NVARCHAR(50)),
       CAST(LEFT(CAST([UpdatedBy] AS NVARCHAR(MAX)), 50) AS NVARCHAR(50))
FROM #stage s
WHERE NOT EXISTS (SELECT 1 FROM mig.Rejects r WHERE r.mapping_id = @mid AND r.action = N'rejected' AND r.source_key = CAST(s.[__src_key] AS NVARCHAR(200)));
INSERT INTO mig.LoadLog (mapping_id, step, row_count) VALUES (@mid, N'loaded', @@ROWCOUNT);
DROP TABLE #stage;
GO
